const order = $input.item.json;

const stateRates = {
  CA: 0.0825,
  NY: 0.08875,
  TX: 0.0625,
  FL: 0.0600
};

const rate = stateRates[order.state] || 0.0500;
const subtotal = Number(order.subtotal || 0);

const taxAmount = Number((subtotal * rate).toFixed(2));
const grandTotal = Number((subtotal + taxAmount).toFixed(2));

return {
  json: {
    orderId: order.orderId,
    subtotal: subtotal,
    state: order.state,
    appliedTaxRate: rate,
    taxAmount: taxAmount,
    grandTotal: grandTotal,
    taxCalculatedAt: new Date().toISOString()
  }
};

const order = $input.item.json;

if (!order.state || String(order.state).trim() === "") {
  throw new Error("CONTRACT_VIOLATION: Missing required parameter 'state'");
}

if (order.subtotal === undefined || order.subtotal === null || order.subtotal === "") {
  throw new Error("CONTRACT_VIOLATION: Missing required parameter 'subtotal'");
}

const subtotal = Number(order.subtotal);

if (!Number.isFinite(subtotal) || subtotal <= 0) {
  throw new Error("CONTRACT_VIOLATION: subtotal must be a positive number");
}

return {
  json: {
    ...order,
    state: String(order.state).trim().toUpperCase(),
    subtotal
  }
};
